    def trader_diary(self, from_date, to_date, save_to: Optional[str] = None) -> ReportFile:
        """
        Day-wise realised PnL diary for a date range.

        This report is XLSX-only — the server ignores the action type and always
        streams a workbook.

        Args:
            from_date: Start date of the range.
            to_date: End date of the range, inclusive.
            save_to (Optional[str]): File or directory to write the report to.

        Returns:
            ReportFile: The XLSX workbook.

        Raises:
            NubraValidationError: If the request fails validation.
        """
        try:
            request = DownloadOnlyDateRangeRequest(
                from_date=from_date,
                to_date=to_date,
                action_type=ReportActionType.DOWNLOAD,
            )
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

        response = self.client.request(
            "post",
            self._url("report/trader-diary"),
            json=request.model_dump(by_alias=True, exclude_none=True),
        )
        return self._file(response, "Daily_PNL.xlsx", save_to)

    def portfolio_snapshot(self, save_to: Optional[str] = None) -> ReportFile:
        """
        Current portfolio workbook — holdings, positions and orders, one sheet each.

        Unlike the other reports this is generated from live trading data rather
        than the back office, takes no date input, and is always XLSX.

        Args:
            save_to (Optional[str]): File or directory to write the report to.

        Returns:
            ReportFile: The XLSX workbook.
        """
        response = self.client.request("get", self._url("report/portfolio"))
        return self._file(response, "portfolio_report.xlsx", save_to)

