    def mf_holdings(
        self,
        date,
        action_type: ReportActionType = ReportActionType.DOWNLOAD,
        save_to: Optional[str] = None,
    ) -> Union[MFHoldingsReportView, ReportFile]:
        """
        Mutual fund holdings as on a single date, valued at the latest NAV, with
        per-scheme and portfolio XIRR.

        Args:
            date: As-on date — ``"YYYY-MM-DD"``, ``date`` or ``datetime``.
            action_type (ReportActionType): VIEW or DOWNLOAD.
            save_to (Optional[str]): File or directory to write the report to.

        Returns:
            MFHoldingsReportView for VIEW, ReportFile (XLSX) for DOWNLOAD.

        Raises:
            NubraValidationError: If the request or the response fail validation.
        """
        try:
            request = ExcelSingleDateReportRequest(date=date, action_type=action_type)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

        return self._post_report(
            "report/holdings",
            request,
            MFHoldingsReportView,
            "holdings_report",
            save_to,
        )

    def mf_capital_gains(
        self,
        from_date,
        to_date,
        action_type: ReportActionType = ReportActionType.DOWNLOAD,
        save_to: Optional[str] = None,
    ) -> Union[MFCapitalGainsReportView, ReportFile]:
        """
        Realised mutual fund capital gains for a date range — redemptions matched
        to allotments FIFO, split into STCG and LTCG.

        Args:
            from_date: Start date of the range.
            to_date: End date of the range, inclusive.
            action_type (ReportActionType): VIEW or DOWNLOAD.
            save_to (Optional[str]): File or directory to write the report to.

        Returns:
            MFCapitalGainsReportView for VIEW, ReportFile (XLSX) for DOWNLOAD.

        Raises:
            NubraValidationError: If the request or the response fail validation.
        """
        try:
            request = ExcelDateRangeReportRequest(
                from_date=from_date, to_date=to_date, action_type=action_type
            )
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

        return self._post_report(
            "report/capital_gains",
            request,
            MFCapitalGainsReportView,
            "capital_gains_report",
            save_to,
        )

